class Solution {
public:
    vector<string> generatePalindromes(string s) {
        unordered_map<char, int> counts;
        for (char c : s) counts[c]++;
        string oddChar = "";
        for (const auto& p : counts) {
            if (p.second % 2 == 1) {
                if (!oddChar.empty()) return {};
                oddChar = p.first;
            }
        }
        string half = "";
        for (const auto& p : counts) {
            half.append(p.second / 2, p.first);
        }
        sort(half.begin(), half.end());
        vector<string> res;
        vector<bool> visited(half.size(), false);
        string path = "";
        backtrack(half, visited, path, oddChar, res);
        return res;
    }

private:
    void backtrack(const string& half, vector<bool>& visited, string& path, const string& oddChar, vector<string>& res) {
        if (path.size() == half.size()) {
            string rev = path;
            reverse(rev.begin(), rev.end());
            res.push_back(path + oddChar + rev);
            return;
        }
        for (size_t i = 0; i < half.size(); ++i) {
            if (visited[i]) continue;
            if (i > 0 && half[i] == half[i - 1] && !visited[i - 1]) continue;
            visited[i] = true;
            path.push_back(half[i]);
            backtrack(half, visited, path, oddChar, res);
            path.pop_back();
            visited[i] = false;
        }
    }
};

class Solution {
    public List<String> generatePalindromes(String s) {
        Map<Character, Integer> counts = new HashMap<>();
        for (char c : s.toCharArray()) {
            counts.put(c, counts.getOrDefault(c, 0) + 1);
        }
        String oddChar = "";
        for (Map.Entry<Character, Integer> entry : counts.entrySet()) {
            if (entry.getValue() % 2 == 1) {
                if (!oddChar.isEmpty()) return new ArrayList<>();
                oddChar = String.valueOf(entry.getKey());
            }
        }
        List<Character> half = new ArrayList<>();
        for (Map.Entry<Character, Integer> entry : counts.entrySet()) {
            int times = entry.getValue() / 2;
            for (int i = 0; i < times; i++) half.add(entry.getKey());
        }
        Collections.sort(half);
        List<String> res = new ArrayList<>();
        boolean[] visited = new boolean[half.size()];
        StringBuilder path = new StringBuilder();
        backtrack(half, visited, path, oddChar, res);
        return res;
    }

    private void backtrack(List<Character> half, boolean[] visited, StringBuilder path, String oddChar, List<String> res) {
        if (path.length() == half.size()) {
            String h = path.toString();
            String rev = new StringBuilder(h).reverse().toString();
            res.add(h + oddChar + rev);
            return;
        }
        for (int i = 0; i < half.size(); i++) {
            if (visited[i]) continue;
            if (i > 0 && half.get(i).equals(half.get(i - 1)) && !visited[i - 1]) continue;
            visited[i] = true;
            path.append(half.get(i));
            backtrack(half, visited, path, oddChar, res);
            path.setLength(path.length() - 1);
            visited[i] = false;
        }
    }
}

