var generatePalindromes = function(s) {
    const counts = new Map();
    for (const c of s) counts.set(c, (counts.get(c) || 0) + 1);
    let oddChar = "";
    for (const [c, cnt] of counts) {
        if (cnt % 2 === 1) {
            if (oddChar !== "") return [];
            oddChar = c;
        }
    }
    const half = [];
    for (const [c, cnt] of counts) {
        const times = Math.floor(cnt / 2);
        for (let i = 0; i < times; i++) half.push(c);
    }
    half.sort();
    const res = [];
    const visited = new Array(half.length).fill(false);
    function backtrack(path) {
        if (path.length === half.length) {
            const h = path.join("");
            const rev = path.slice().reverse().join("");
            res.push(h + oddChar + rev);
            return;
        }
        for (let i = 0; i < half.length; i++) {
            if (visited[i]) continue;
            if (i > 0 && half[i] === half[i - 1] && !visited[i - 1]) continue;
            visited[i] = true;
            path.push(half[i]);
            backtrack(path);
            path.pop();
            visited[i] = false;
        }
    }
    backtrack([]);
    return res;
};
